WITH tables AS (
 SELECT c.oid,c.relname,c.relkind::text,c.relpersistence::text,c.relispartition,c.relrowsecurity,c.relforcerowsecurity,c.relreplident::text
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN
 ('wait_owner_budgets','wait_owner_projects','wait_owner_tasks','wait_owner_records','wait_owner_members','wait_owner_edges','wait_owner_work','wait_owner_slots')
), objects AS (
 SELECT 'table' AS kind,relname AS name,to_jsonb(t)-'oid' AS body FROM tables t
 UNION ALL SELECT 'column',t.relname||'.'||a.attname,jsonb_build_object('number',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'required',a.attnotnull,'generated',a.attgenerated::text,'identity',a.attidentity::text,'default',pg_get_expr(d.adbin,d.adrelid),'storage',a.attstorage::text,'collation',CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::regcollation::text END) FROM tables t JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 UNION ALL SELECT 'constraint',t.relname||'.'||c.conname,jsonb_build_object('type',c.contype::text,'validated',c.convalidated,'deferrable',c.condeferrable,'deferred',c.condeferred,'definition',pg_get_constraintdef(c.oid,false)) FROM tables t JOIN pg_constraint c ON c.conrelid=t.oid
 UNION ALL SELECT 'index',t.relname||'.'||i.relname,jsonb_build_object('definition',pg_get_indexdef(x.indexrelid),'valid',x.indisvalid,'ready',x.indisready,'live',x.indislive,'primary',x.indisprimary,'unique',x.indisunique,'nulls_not_distinct',x.indnullsnotdistinct,'exclusion',x.indisexclusion,'immediate',x.indimmediate) FROM tables t JOIN pg_index x ON x.indrelid=t.oid JOIN pg_class i ON i.oid=x.indexrelid
 UNION ALL SELECT 'trigger',t.relname||'.'||g.tgname,jsonb_build_object('definition',pg_get_triggerdef(g.oid,false),'enabled',g.tgenabled::text,'internal',g.tgisinternal,'type',g.tgtype,'deferrable',g.tgdeferrable,'deferred',g.tginitdeferred) FROM tables t JOIN pg_trigger g ON g.tgrelid=t.oid AND NOT g.tgisinternal
 UNION ALL SELECT 'fk_internal_trigger',r.relname||'.'||c.conname||'.'||p.proname||'.'||g.tgtype::text,jsonb_build_object('enabled',g.tgenabled::text,'internal',g.tgisinternal,'type',g.tgtype,'deferrable',g.tgdeferrable,'deferred',g.tginitdeferred,'function',p.proname,'constraint',c.conname,'from_table',c.conrelid::regclass::text,'to_table',c.confrelid::regclass::text) FROM pg_trigger g JOIN pg_constraint c ON c.oid=g.tgconstraint JOIN pg_class r ON r.oid=g.tgrelid JOIN pg_proc p ON p.oid=g.tgfoid WHERE g.tgisinternal AND c.contype='f' AND (c.conrelid IN(SELECT oid FROM tables) OR c.confrelid IN(SELECT oid FROM tables))
 UNION ALL SELECT 'function',p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',jsonb_build_object('body',p.prosrc,'args',pg_get_function_arguments(p.oid),'returns',pg_get_function_result(p.oid),'language',l.lanname,'volatility',p.provolatile::text,'kind',p.prokind::text,'security_definer',p.prosecdef,'set',p.proretset,'strict',p.proisstrict,'parallel',p.proparallel::text,'config',p.proconfig) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='public' AND p.proname LIKE 'wait38\_%' ESCAPE '\'
)
SELECT COALESCE(jsonb_agg(jsonb_build_object('kind',kind,'name',name,'body',body) ORDER BY kind,name),'[]'::jsonb) FROM objects
